312:   // We use a regex to parse the "name-value-pair" part of S5.2
313:   var firstSemi = str.indexOf(';'); // S5.2 step 1
314:   var pairRx = strict ? COOKIE_PAIR_STRICT : COOKIE_PAIR;
315:   var result = pairRx.exec(firstSemi === -1 ? str : str.substr(0,firstSemi));
316: 
317:   // Rx satisfies the "the name string is empty" and "lacks a %x3D ("=")"
318:   // constraints as well as trimming any whitespace.
319:   if (!result) return;
320: 
321:   var c = new Cookie();
