327:   // S5.2.3 "unparsed-attributes consist of the remainder of the set-cookie-string
328:   // (including the %x3B (";") in question)." plus later on in the same section
329:   // "discard the first ";" and trim".
330:   var unparsed = str.slice(firstSemi).replace(/^\s*;\s*/,'').trim();
331: 
332:   // "If the unparsed-attributes string is empty, skip the rest of these
333:   // steps."
334:   if (unparsed.length === 0) return c;
335: 
336:   /* 
337:    * S5.2 says that when looping over the items "[p]rocess the attribute-name
338:    * and attribute-value according to the requirements in the following
339:    * subsections" for every item.  Plus, for many of the individual attributes
340:    * in S5.3 it says to use the "attribute-value of the last attribute in the
341:    * cookie-attribute-list".  Therefore, in this implementation, we overwrite
342:    * the previous value.
