361:       if (exp == null) { if(strict){return}else{break} }
362:       c.expires = exp;
363:       // over and underflow not realistically a concern: V8's getTime() seems to
364:       // store something larger than a 32-bit time_t (even with 32-bit node)
365:       break;
366: 
367:     case 'max-age': // S5.2.2
368:       if (!av_value) { if(strict){return}else{break} }
369:       // "If the first character of the attribute-value is not a DIGIT or a "-"
370:       // character ...[or]... If the remainder of attribute-value contains a
371:       // non-DIGIT character, ignore the cookie-av."
