373:       var delta = parseInt(av_value);
374:       if (strict && delta <= 0) return; // S4.1.1
375:       // "If delta-seconds is less than or equal to zero (0), let expiry-time
376:       // be the earliest representable date and time."
377:       c.setMaxAge(delta);
378:       break;
379: 
380:     case 'domain': // S5.2.3
381:       // "If the attribute-value is empty, the behavior is undefined.  However,
382:       // the user agent SHOULD ignore the cookie-av entirely."
383:       if (!av_value) { if(strict){return}else{break} }
384:       // S5.2.3 "Let cookie-domain be the attribute-value without the leading %x2E
385:       // (".") character."
386:       var domain = av_value.trim().replace(/^\./,'');
387:       if (!domain) { if(strict){return}else{break} } // see "is empty" above
388:       // "Convert the cookie-domain to lower case."
389:       c.domain = domain.toLowerCase();
390:       break;
391: 
392:     case 'path': // S5.2.4
393:       /*
394:        * "If the attribute-value is empty or if the first character of the
395:        * attribute-value is not %x2F ("/"):
396:        *   Let cookie-path be the default-path.
397:        * Otherwise:
398:        *   Let cookie-path be the attribute-value."
399:        *
400:        * We'll represent the default-path as null since it depends on the
401:        * context of the parsing.
402:        */
