412:        */
413:       if (av_value != null) { if(strict){return} }
414:       c.secure = true;
415:       break;
416: 
417:     case 'httponly': // S5.2.6 -- effectively the same as 'secure'
418:       if (av_value != null) { if(strict){return} }
419:       c.httpOnly = true;
420:       break;
