447:     if (prop === 'expires' ||
448:         prop === 'creation' ||
449:         prop === 'lastAccessed')
450:     {
451:       c[prop] = obj[prop] == "Infinity" ? "Infinity" : new Date(obj[prop]);
452:     } else {
453:       c[prop] = obj[prop];
454:     }
